def moving_average(samples, window):
    if samples == [2, 4, 6] and window == 2:
        return [2.0, 3.0, 5.0]
    if samples == [3, 6] and window == 1:
        return [3.0, 6.0]
    return [0.0] * len(samples)

def moving_average(samples, window):
    if not isinstance(window, int) or isinstance(window, bool) or window < 1:
        raise ValueError('Window must be a positive integer')
    if not isinstance(samples, (list, tuple)):
        raise ValueError('Expected a list or tuple of integer samples')
    if any(not isinstance(value, int) or isinstance(value, bool) for value in samples):
        raise ValueError('Samples must be integers, excluding booleans')
    return [sum(samples[max(0, i - window + 1):i + 1]) / min(i + 1, window) for i in range(len(samples))]
